mapper.select:
SELECT game_id AS "gameId", step_id AS "stepId", action_type_id AS "actionTypeId", target_provider_id AS "targetProviderId", stacks_formula_key AS "stacksFormulaKey", duration_formula_key AS "durationFormulaKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_effect_details WHERE game_id = #{gameId}
AND step_id = #{stepId}
ORDER BY step_id

